const stdout = $json.stdout || '';
const files = stdout.split('\n').map(f => f.trim()).filter(Boolean);
return files.map(file => ({ json: { filePath: file } }));

const parseExcel = require('/Users/a12/projects/ev-export-management-leo/scripts/parse_excel');
const rows = parseExcel.parseExcelFile($json.filePath);
return rows.map(r => ({ json: r }));

const stdout = $json.stdout || '';
const files = stdout.split('\n').map(f => f.trim()).filter(Boolean);
const validFiles = files.filter(f => /\.(png|jpg|jpeg|webp|pdf)$/i.test(f));
return validFiles.map(file => ({ json: { filePath: file } }));

const filePath = $json.filePath;
const { execSync } = require('child_process');
const escapedPath = filePath.replace(/"/g, '\"');
let parsed = { text: "", need_vision: true };
try {
  const stdout = execSync(`python3 /Users/a12/projects/ev-export-management-leo/scripts/parse_document.py "${escapedPath}"`, { encoding: 'utf-8' });
  parsed = JSON.parse(stdout);
} catch (e) {
  parsed = { text: "", need_vision: true, error: e.message };
}
return { json: { filePath, ...parsed } };

const filePath = $json.filePath;
const needVision = $json.need_vision;
const extractedText = $json.text;

const systemPrompt = "你是车源导入解析助手。请把车源文件解析为严格 JSON。顶层必须包含 candidates 数组。字段必须使用：brand, modelName, year, trimName, priceExw, priceExwCurrency, priceFob, priceFobCurrency, priceFca, priceFcaCurrency, officialPrice, location, stockQuantity, notes。";

let parts = [];
if (needVision) {
  const fs = require('fs');
  const base64Data = fs.readFileSync(filePath).toString('base64');
  const mimeType = filePath.endsWith('.pdf') ? 'application/pdf' : (filePath.endsWith('.png') ? 'image/png' : (filePath.endsWith('.webp') ? 'image/webp' : 'image/jpeg'));
  parts = [
    { text: systemPrompt },
    {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    }
  ];
} else {
  parts = [
    { text: systemPrompt + "\n\n以下是待提取的文档文本内容/OCR结果：\n" + extractedText }
  ];
}

const payload = {
  contents: [{ parts }],
  generationConfig: {
    responseMimeType: "application/json",
    temperature: 0.1
  }
};

return { json: payload };

const excelRows = [];
try {
  const parseItems = $items('Parse Excel Rows');
  for (const item of parseItems) {
    excelRows.push(item.json);
  }
} catch(e) {}

const aiRows = [];
try {
  const geminiItems = $items('Gemini Vision Extract');
  for (const item of geminiItems) {
    const text = item.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    const parsed = JSON.parse(text);
    if (parsed.candidates) aiRows.push(...parsed.candidates);
  }
} catch(e) {}

return [...excelRows, ...aiRows].map(row => ({ json: row }));

const ruleEnginePath = '/Users/a12/projects/ev-export-management-leo/scripts/learning_engine.js';
let engine;
try {
  engine = require(ruleEnginePath);
} catch (e) {}

const items = $input.all();
const candidates = items.map(item => item.json);

if (engine) {
  const corrected = engine.applyRulesToBatch(candidates);
  return corrected.map(r => ({ json: r.candidate }));
}

return items;

const items = $input.all();

const parsedItems = items.map(item => {
  const row = item.json;

  const toNum = (val) => {
    if (val === undefined || val === null || val === '') return null;
    const cleanStr = String(val).replace(/[^0-9.]/g, '');
    const num = Number(cleanStr);
    return isNaN(num) || cleanStr === '' ? null : num;
  };

  let steering = null;
  const steerRaw = String(row.steeringSetup || row.notes || row.trimName || row.steering_setup || '').toUpperCase();
  if (steerRaw.includes('左舵') || steerRaw.includes('LHD')) {
    steering = '左舵';
  } else if (steerRaw.includes('右舵') || steerRaw.includes('RHD')) {
    steering = '右舵';
  }

  let market = null;
  const marketRaw = String(row.marketRegion || row.notes || row.trimName || row.market_region || '');
  if (marketRaw.includes('国内') || marketRaw.includes('中规')) {
    market = ['国内版'];
  } else if (marketRaw.includes('国际') || marketRaw.includes('出口') || marketRaw.includes('海外') || marketRaw.includes('欧标') || marketRaw.includes('美规')) {
    market = ['国际版'];
  }

  let waitDays = toNum(row.orderWaitDays || row.order_wait_days);
  if (waitDays === null && row.leadTimeText) {
    const textStr = String(row.leadTimeText);
    const mRangeWeek = textStr.match(/(\d+)\s*[-~至]\s*(\d+)\s*周/);
    if (mRangeWeek) {
      waitDays = Number(mRangeWeek[2]) * 7;
    } else {
      const mSingleWeek = textStr.match(/(\d+)\s*周/);
      if (mSingleWeek) {
        waitDays = Number(mSingleWeek[1]) * 7;
      } else {
        const mDays = textStr.match(/(\d+)\s*天/);
        if (mDays) {
          waitDays = Number(mDays[1]);
        }
      }
    }
  }

  const fields = {
    brand: row.brand || null,
    model: row.modelName || row.model || null,
    trim_config: row.trimName || row.trimConfig || row.trim_config || null,
    exterior_color: row.exteriorColor || row.exterior_color || null,
    interior_color: row.interiorColor || row.interior_color || null,
    stock_quantity: toNum(row.stockQuantity || row.stock_quantity),
    supplier: row.supplierName || row.supplier || null,
    location: row.location || null,
    notes: row.notes || null,
    official_suggested_price_cny: toNum(row.officialPrice || row.officialPriceCny || row.official_suggested_price_cny),
    cost_exw_usd: toNum(row.priceExw || row.costExwUsd || row.cost_exw_usd),
    cost_fob_usd: toNum(row.priceFob || row.costFobUsd || row.cost_fob_usd),
    cost_fca_usd: toNum(row.priceFca || row.costFcaUsd || row.cost_fca_usd),
    cost_cif_usd: toNum(row.priceCif || row.costCifUsd || row.cost_cif_usd),
    min_quantity: toNum(row.minQuantity || row.min_quantity),
    max_quantity: toNum(row.maxQuantity || row.max_quantity),
    steering_setup: steering,
    market_region: market,
    order_wait_days: waitDays
  };

  return { json: fields };
});

return parsedItems;
